package net.officefloor.hq.app.invoice;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Collection;
import java.util.List;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface InvoiceRepository extends JpaRepository<Invoice, Long> {

    List<Invoice> findByProjectIdOrderById(Long projectId);

    /** All invoices across every project, with their project loaded in the same query. */
    @Query("SELECT i FROM Invoice i JOIN FETCH i.project ORDER BY i.id")
    List<Invoice> findAllWithProject();

    /** Invoices across every project at the given status, with their project loaded in the same query. */
    @Query("SELECT i FROM Invoice i JOIN FETCH i.project WHERE i.status = :status ORDER BY i.id")
    List<Invoice> findAllWithProjectByStatus(InvoiceStatus status);

    /** One page of the invoices across every project, with their project loaded in the same query. */
    @Query(value = "SELECT i FROM Invoice i JOIN FETCH i.project ORDER BY i.id",
            countQuery = "SELECT COUNT(i) FROM Invoice i")
    Page<Invoice> findPageWithProject(Pageable pageable);

    /** One page of the invoices at the given status, with their project loaded in the same query. */
    @Query(value = "SELECT i FROM Invoice i JOIN FETCH i.project WHERE i.status = :status ORDER BY i.id",
            countQuery = "SELECT COUNT(i) FROM Invoice i WHERE i.status = :status")
    Page<Invoice> findPageWithProjectByStatus(InvoiceStatus status, Pageable pageable);

    /** A client's invoices across all of their projects, with their project loaded in the same query. */
    @Query("SELECT i FROM Invoice i JOIN FETCH i.project p WHERE p.client.id = :clientId ORDER BY i.id")
    List<Invoice> findByClientIdWithProject(Long clientId);

    /** Sum of the amounts of all invoices with any of the given statuses (zero when there are none). */
    @Query("SELECT COALESCE(SUM(i.amount), 0) FROM Invoice i WHERE i.status IN :statuses")
    BigDecimal sumAmountByStatusIn(Collection<InvoiceStatus> statuses);

    /** Number of invoices with any of the given statuses whose due date is before the given date. */
    @Query("SELECT COUNT(i) FROM Invoice i WHERE i.status IN :statuses AND i.dueDate < :date")
    long countByStatusInAndDueDateBefore(Collection<InvoiceStatus> statuses, LocalDate date);
}
package net.officefloor.hq.app.invoice;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.OneToMany;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.project.Project;

/**
 * An invoice raised against a project. It is built from line items, and can take a percentage off
 * their sum as a discount, then add a percentage sales tax on what is left; its stored amount is always
 * that subtotal less the discount plus the tax.
 */
@Entity
@Table(name = "invoice")
public class Invoice {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "project_id", nullable = false)
    private Project project;

    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal amount = BigDecimal.ZERO.setScale(2);

    @Column(name = "discount_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal discountPct = BigDecimal.ZERO.setScale(2);

    @Column(name = "tax_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal taxPct = BigDecimal.ZERO.setScale(2);

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 16)
    private InvoiceStatus status = InvoiceStatus.DRAFT;

    @Column(name = "issued_date", nullable = false)
    private LocalDate issuedDate;

    @Column(name = "due_date", nullable = false)
    private LocalDate dueDate;

    @OneToMany(mappedBy = "invoice", cascade = CascadeType.ALL, orphanRemoval = true)
    @OrderBy("id")
    private List<InvoiceLineItem> lineItems = new ArrayList<>();

    protected Invoice() {
    }

    public Invoice(Project project, LocalDate issuedDate, LocalDate dueDate) {
        this.project = project;
        this.issuedDate = issuedDate;
        this.dueDate = dueDate;
    }

    public Long getId() {
        return id;
    }

    public Project getProject() {
        return project;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    /** The percentage taken off the subtotal; zero when there is no discount. */
    public BigDecimal getDiscountPct() {
        return discountPct;
    }

    /** What the line items add up to, before any discount. */
    public BigDecimal getSubtotal() {
        return lineItems.stream().map(InvoiceLineItem::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add)
                .setScale(2, RoundingMode.HALF_UP);
    }

    /** How much the discount takes off the subtotal, to the cent. */
    public BigDecimal getDiscount() {
        return discountOn(getSubtotal());
    }

    /** The sales tax percentage added after the discount; zero when there is no tax. */
    public BigDecimal getTaxPct() {
        return taxPct;
    }

    /** How much sales tax is added to the discounted subtotal, to the cent. */
    public BigDecimal getTax() {
        BigDecimal subtotal = getSubtotal();
        return taxOn(subtotal.subtract(discountOn(subtotal)));
    }

    public InvoiceStatus getStatus() {
        return status;
    }

    public LocalDate getIssuedDate() {
        return issuedDate;
    }

    public LocalDate getDueDate() {
        return dueDate;
    }

    public List<InvoiceLineItem> getLineItems() {
        return List.copyOf(lineItems);
    }

    /** Adds a line to this invoice and reworks its amount to include what the line charges. */
    public InvoiceLineItem addLineItem(String description, BigDecimal qty, String unit, BigDecimal unitPrice) {
        InvoiceLineItem item = new InvoiceLineItem(this, description, qty, unit, unitPrice);
        lineItems.add(item);
        recalculateAmount();
        return item;
    }

    /** Changes one of this invoice's lines and reworks its amount to match. */
    public void updateLineItem(InvoiceLineItem item, String description, BigDecimal qty, String unit,
            BigDecimal unitPrice) {
        item.update(description, qty, unit, unitPrice);
        recalculateAmount();
    }

    /** Removes a line from this invoice and reworks its amount to no longer include what the line charged. */
    public void removeLineItem(InvoiceLineItem item) {
        lineItems.remove(item);
        recalculateAmount();
    }

    /** The line on this invoice with the given id, if there is one. */
    public Optional<InvoiceLineItem> findLineItem(Long lineItemId) {
        return lineItems.stream().filter(l -> l.getId().equals(lineItemId)).findFirst();
    }

    /** Sets the percentage taken off this invoice and reworks its amount to match. */
